int powMod(int a, int b){
    ll res = 1;
    for(int i = 1; i <= b; i++){
        res *= a;   // res tràn khi b lớn
    }
    return res % 10;
}

int powMod(int a, int b){
    ll res = 1;
    for(int i = 1; i <= b; i++){
        res *= (a % 10);
        res %= 10;   // quan trọng
    }
    return res;
}

ll powMod(ll a, ll b, ll c){
    ll res = 1;
    while(b){
        if(b % 2 == 1){ res *= a; res %= c; }
        a *= a; a %= c;
        b /= 2;
    }
    return res;
}

